class Payment {
    protected String txId;
    protected double amount;
    protected boolean completed;

    public Payment(String txId, double amount) {
        this.txId = txId;
        this.amount = amount;
        this.completed = false;
    }

    public double calculateFee() {
        return 0.0; // Default: zero fee
    }

    public boolean processPayment() {
        if (amount <= 0) {
            System.out.println("[" + txId + "] Rejected: Invalid amount");
            return false;
        }
        completed = true;
        System.out.println("[" + txId + "] Base clearance approved: $" + String.format("%.2f", amount));
        return true;
    }

    public void printReceipt() {
        double total = amount + calculateFee();
        System.out.println("=== Receipt (" + txId + ") ===");
        System.out.println("Principal: $" + String.format("%.2f", amount));
        System.out.println("Fee: $" + String.format("%.2f", calculateFee()));
        System.out.println("Total Charged: $" + String.format("%.2f", total));
        System.out.println("Status: " + (completed ? "SUCCESS" : "PENDING"));
    }
}

class CreditCardPayment extends Payment {
    private String cardNumber;

    public CreditCardPayment(String txId, double amount, String cardNumber) {
        super(txId, amount);
        this.cardNumber = cardNumber;
    }

    @Override
    public double calculateFee() {
        return amount * 0.025; // 2.5% card fee
    }

    @Override
    public boolean processPayment() {
        System.out.println("[" + txId + "] Contacting Visa/Mastercard network for card ending in " + cardNumber.substring(cardNumber.length() - 4));
        return super.processPayment(); // Augment with parent validation
    }
}

public class PaymentTest {
    public static void main(String[] args) {
        Payment p = new CreditCardPayment("TX-101", 200.0, "4111222233334444");
        p.processPayment();
        p.printReceipt();
    }
}

