class PayPalPayment extends Payment {
    private String email;
    public PayPalPayment(String txId, double amount, String email) {
        super(txId, amount);
        this.email = email;
    }
    @Override
    public double calculateFee() {
        return 0.30 + (amount * 0.015); // Flat $0.30 + 1.5%
    }
    @Override
    public boolean processPayment() {
        System.out.println("[" + txId + "] Authenticating PayPal account: " + email);
        return super.processPayment();
    }
}

class CryptoPayment extends Payment {
    private String walletAddress;
    public CryptoPayment(String txId, double amount, String walletAddress) {
        super(txId, amount);
        this.walletAddress = walletAddress;
    }
    @Override
    public double calculateFee() {
        return 1.50; // Fixed network gas fee
    }
    @Override
    public boolean processPayment() {
        System.out.println("[" + txId + "] Broadcasting to blockchain for wallet: " + walletAddress);
        return super.processPayment();
    }
}

public class BatchCheckoutApp {
    public static void processBatch(Payment[] batch) {
        double totalRevenue = 0;
        for (Payment payment : batch) {
            boolean ok = payment.processPayment();
            if (ok) {
                totalRevenue += (payment.amount + payment.calculateFee());
            }
            System.out.println("----------------------------------------");
        }
        System.out.println("Total Settled Funds: $" + String.format("%.2f", totalRevenue));
    }

    public static void main(String[] args) {
        Payment[] transactions = new Payment[] {
            new CreditCardPayment("TX-01", 100.0, "4111222233331111"),
            new PayPalPayment("TX-02", 50.0, "customer@email.com"),
            new CryptoPayment("TX-03", 250.0, "0x71C...9B1")
        };
        processBatch(transactions);
    }
}

