    }
    @Override
    public double getFee() {
        return amount * 0.03;
    }
}

public class PaymentFeeApp {
    public static void main(String[] args) {
        Payment payment = new CreditCardPayment(200.0);
        System.out.println("Fee: $" + payment.getFee());
    }
}

class PaymentMethod {
    protected String accountName;
    protected double amount;
    public PaymentMethod(String accountName, double amount) {
        this.accountName = accountName;
        this.amount = amount;
    }
    public String settle() {
        return accountName + ": Settled $" + amount;
    }
}

class DirectDebit extends PaymentMethod {
    public DirectDebit(String accountName, double amount) {
        super(accountName, amount);
    }
    @Override
    public String settle() {
        return accountName + ": ACH Transfer Settled $" + amount;
    }
}

class WireTransfer extends PaymentMethod {
    private double wireFee = 15.0;
    public WireTransfer(String accountName, double amount) {
        super(accountName, amount);
    }
    @Override
    public String settle() {
        return accountName + ": Wire Settled $" + (amount + wireFee) + " (includes $15 fee)";
    }
}

public class SettlementEngineApp {
    public static void main(String[] args) {
        PaymentMethod[] batch = new PaymentMethod[] {
            new DirectDebit("Corp Account A", 1200.0),
            new WireTransfer("Overseas Supplier", 5000.0)
        };
        for (PaymentMethod pm : batch) {
            System.out.println(pm.settle());
        }
    }
}

class RefundRequest {
    protected String txId;
    protected double amount;
    public RefundRequest(String txId, double amount) {
        this.txId = txId;
        this.amount = amount;
    }
    public boolean authorize() {
        if (amount > 0) {
            System.out.println("[Base] Refund authorized for " + txId + ": $" + amount);
            return true;
        }
        return false;
    }
}

class CardRefund extends RefundRequest {
    public CardRefund(String txId, double amount) {
        super(txId, amount);
    }
    @Override
    public boolean authorize() {
        System.out.println("[Card] Verifying original charge for " + txId);
        boolean ok = super.authorize();
        if (ok) {
            System.out.println("[Card] Acquirer refund token generated");
        }
        return ok;
    }
}

public class RefundApp {
    public static void main(String[] args) {
        RefundRequest refund = new CardRefund("TX-8821", 75.50);
        refund.authorize();
    }
}

