class Invoice {
    protected double amount;
    public Invoice(double amount) { this.amount = amount;
    }
    // BUG: Method is static, disabling polymorphism
    public static double computeDiscount(double total) {
        return total * 0.05; // 5% default discount
    }
    public void printSummary() {
        // BUG: Invocations to computeDiscount resolve statically to Invoice.computeDiscount
        double discount = computeDiscount(amount);
        System.out.println("Total: $" + (amount - discount));
    }
}

class VipInvoice extends Invoice {
    public VipInvoice(double amount) {
        super(amount);
    }
    // BUG: Trying to hide static method
    public static double computeDiscount(double total) {
        return total * 0.20; // 20% VIP discount
    }
}

public class InvoiceBugApp {
    public static void main(String[] args) {
        Invoice inv = new VipInvoice(100.0);
        inv.printSummary(); // Expected 80.0, but prints 95.0!
    }
}

