class GatewayPayment {
    protected String txId;
    protected double amount;
    public GatewayPayment(String txId, double amount) {
        this.txId = txId;
        this.amount = amount;
    }
    public double getProcessingFee() {
        return 0.0;
    }
    public String getMethodName() {
        return "STANDARD";
    }
    public void execute() {
        double total = amount + getProcessingFee();
        System.out.println("[" + getMethodName() + "] Settled $" + String.format("%.2f", total));
    }
}

class StripeGateway extends GatewayPayment {
    public StripeGateway(String txId, double amount) {
        super(txId, amount);
    }
    @Override
    public String getMethodName() {
        return "STRIPE_CARD";
    }
    @Override
    public double getProcessingFee() {
        return (amount * 0.029) + 0.30;
    }
}

class ApplePayGateway extends GatewayPayment {
    public ApplePayGateway(String txId, double amount) {
        super(txId, amount);
    }
    @Override
    public String getMethodName() {
        return "APPLE_PAY";
    }
    @Override
    public double getProcessingFee() {
        return amount * 0.015;
    }
}

class CryptoGateway extends GatewayPayment {
    public CryptoGateway(String txId, double amount) {
        super(txId, amount);
    }
    @Override
    public String getMethodName() {
        return "CRYPTO_ETH";
    }
    @Override
    public double getProcessingFee() {
        return 4.50;
    }
}

public class GatewayBatchApp {
    public static void main(String[] args) {
        GatewayPayment[] transactions = new GatewayPayment[] {
            new StripeGateway("TX-01", 100.0),
            new ApplePayGateway("TX-02", 200.0),
            new CryptoGateway("TX-03", 50.0)
        };
        for (GatewayPayment gp : transactions) {
            gp.execute();
        }
    }
}
